<script>const desktopGroups=document.querySelectorAll('.school-desktop-group');desktopGroups.forEach(group=>group.querySelector('.school-desktop-trigger').addEventListener('click',event=>{event.stopPropagation();const open=!group.classList.contains('is-open');desktopGroups.forEach(item=>item.classList.remove('is-open'));group.classList.toggle('is-open',open)}));const mobileToggle=document.querySelector('.school-mobile-toggle'),mobileMenu=document.querySelector('.school-mobile-menu'),closeMobileSubmenus=()=>{document.querySelectorAll('.school-mobile-sub').forEach(item=>item.classList.remove('is-open'));document.querySelectorAll('.school-mobile-group').forEach(item=>item.classList.remove('is-open'))};const setMobileMenuOpen=open=>{mobileMenu.classList.toggle('is-open',open);mobileToggle.classList.toggle('is-open',open);mobileToggle.setAttribute('aria-expanded',String(open));mobileToggle.setAttribute('aria-label',open?'Tutup menu':'Buka menu');if(!open)closeMobileSubmenus()};
mobileToggle?.addEventListener('click',()=>setMobileMenuOpen(!mobileMenu.classList.contains('is-open')));
document.addEventListener('click',event=>{if(!mobileToggle.closest('.school-nav').contains(event.target))setMobileMenuOpen(false)});
mobileMenu.addEventListener('click',event=>{if(event.target.closest('a'))setMobileMenuOpen(false)});
document.addEventListener('keydown',event=>{if(event.key==='Escape'&&mobileMenu.classList.contains('is-open')){setMobileMenuOpen(false);mobileToggle.focus()}});
window.matchMedia('(min-width:901px)').addEventListener('change',event=>{if(event.matches)setMobileMenuOpen(false)});document.querySelectorAll('.school-mobile-group').forEach(button=>button.addEventListener('click',()=>{const sub=button.nextElementSibling,open=!sub.classList.contains('is-open');closeMobileSubmenus();sub.classList.toggle('is-open',open);button.classList.toggle('is-open',open)}));document.addEventListener('click',event=>desktopGroups.forEach(group=>{if(!group.contains(event.target))group.classList.remove('is-open')}));</script>
<script>document.addEventListener('DOMContentLoaded',()=>{const url="{{ route('tentang.page','sambutan-kepala-sekolah') }}",label='Sambutan Kepala Sekolah';const desktop=document.querySelector('.school-desktop-sub');if(desktop&&!desktop.querySelector('[href*="sambutan-kepala-sekolah"]'))desktop.insertAdjacentHTML('beforeend',`<a href="${url}">${label}</a>`);const mobile=document.querySelector('.school-mobile-sub div');if(mobile&&!mobile.querySelector('[href*="sambutan-kepala-sekolah"]'))mobile.insertAdjacentHTML('beforeend',`<a href="${url}">${label}</a>`)});</script>
